  const play=append(section('code-playground','BREAK IT / FIGURE IT OUT','A little less theory.<br><span class="muted">A little more play.</span>','Repair a tiny interface, try a language pattern,<br>or step into a text adventure.',`<div class="lab-split"><article class="lab-panel"><span class="eyebrow">01 / BUG HUNT</span><h3>Something’s off.</h3><div class="bug-preview" id="bug-preview"><div class="bug-card"><strong>FOCUSED ON TOM</strong><p>A little card with a few fixable problems.</p><button id="bug-demo-button">Explore</button></div></div><p id="bug-description"></p><div class="lab-tabs" id="bug-options"></div><output id="bug-result" aria-live="polite"></output>${button('NEXT BUG ↗','next-bug')}</article><article class="lab-panel"><span class="eyebrow">02 / LANGUAGE PLAYGROUND</span><h3>One idea.<br>Different syntax.</h3><label class="lab-range">Language<select id="language-choice"><option>Python</option><option>JavaScript</option><option>C++</option><option>Java</option><option>C#</option><option>HTML/CSS</option></select></label><label class="lab-range">Items to count<input type="text" id="language-items" maxlength="200" value="camera, code, camp"></label><pre id="language-code"></pre>${button('RUN THE EXAMPLE','language-run')}<output id="language-output" aria-live="polite"></output><p class="fine-print">Example only; custom code isn’t executed.</p></article></div><article class="lab-panel text-adventure"><span class="eyebrow">03 / TAKE THE LONG WAY</span><h3 id="adventure-title"></h3><p id="adventure-copy"></p><div class="lab-actions" id="adventure-choices"></div></article>`));
  const bugs=[['overflow','The card spills outside its frame.',['Add a larger shadow','Constrain the width','Increase font size'],1],['contrast','The label is hard to read.',['Increase text contrast','Reduce opacity','Blur the background'],0],['spacing','The content needs room to breathe.',['Remove the padding','Hide the paragraph','Add consistent padding'],2],['button','The button is disabled.',['Add more animation','Enable the action','Make the text smaller'],1],['image','The reference image is stretched.',['Use object-fit: cover','Double the height','Hide all overflow'],0],['mobile','The row refuses to fit a narrow screen.',['Force a wider page','Allow wrapping','Shrink every word'],1]];let bug=0,solved=false;
  function bugShow(){solved=false;const [kind,copy,options]=bugs[bug];$('#bug-preview').className='bug-preview bug-'+kind;$('#bug-description').textContent=copy;$('#bug-result').textContent='Choose a fix.';$('#bug-demo-button').disabled=kind==='button';$('#bug-options').innerHTML=options.map((o,i)=>`<button data-fix="${i}">${o}</button>`).join('');$$('[data-fix]').forEach(b=>b.onclick=()=>{solved=+b.dataset.fix===bugs[bug][3];$('#bug-result').textContent=solved?'Fixed. That change addresses the cause.':'Try again. Look at what the content needs.';if(solved){$('#bug-preview').className='bug-preview bug-fixed';$('#bug-demo-button').disabled=false;T.unlock('terminal')}})}
