  const snippets={Python:'items = ["camera", "code", "camp"]\nprint(len(items))',JavaScript:'const items = ["camera", "code", "camp"];\nconsole.log(items.length);','C++':'std::vector<std::string> items = {"camera", "code", "camp"};\nstd::cout << items.size();',Java:'var items = List.of("camera", "code", "camp");\nSystem.out.println(items.size());','C#':'string[] items = {"camera", "code", "camp"};\nConsole.WriteLine(items.Length);','HTML/CSS':'<ul class="interests">\n  <li>camera</li><li>code</li><li>camp</li>\n</ul>\n.interests { display: flex; gap: 1rem; }'};
  $('#language-choice').onchange=()=>{$('#language-code').textContent=snippets[$('#language-choice').value];$('#language-output').textContent=''};$('#language-choice').onchange();$('#language-run').onclick=()=>{const items=$('#language-items').value.split(',').map(s=>s.trim()).filter(Boolean);$('#language-output').textContent=($('#language-choice').value==='HTML/CSS'?'List preview: '+items.join(' · '):'Result: '+items.length+' items')+' · Custom input evaluated by this portfolio demo.'};
  const story={start:['The trailhead','A path leads toward water. A smaller trail disappears into the woods. Somewhere behind you, there’s still a project open on the computer.',[['Follow the lake','lake'],['Head into the woods','woods'],['Return to the desk','desk']]],lake:['A ripple breaks the surface.','You stop for a moment. The best part of this route might be having enough time to notice it.',[['Take a photograph','photo'],['Keep walking','woods']]],woods:['A place to pause.','A clearing, the sound of the trees, and an idea for a small camp.',[['Set up camp','camp'],['Back to the trailhead','start']]],desk:['One more idea.','The trip becomes a field note. The field note becomes an interface. You open a new file.',[['Build something','build'],['Actually go outside','start']]],photo:['Keep the moment.','A frame becomes a story. The story gives you a reason to return.',[['Continue into the woods','woods'],['Try another route','start']]],camp:['Let the day slow down.','The route ends here for a while. No score. Just a place to be.',[['Head home','desk'],['Start another journey','start']]],build:['Curiosity, compiled.','Something from outside has found its way into the code. That is usually how it goes.',[['Find another idea','start'],['Visit the Workshop','workshop']]]};
