  const camp=append(section('camp-builder','MAKE A LITTLE ROOM OUTSIDE','Your camp.<br><span class="muted">Your pace.</span>','Arrange a conceptual camp plan.<br>Drag the labels, or select one and use the arrow keys.',`<div class="lab-split"><div class="camp-plan" id="camp-plan" tabindex="0" aria-label="Camp arrangement. Select equipment, then use arrow keys to move it."><span class="plan-label">CAMPSITE / SCHEMATIC PLAN</span><div class="camp-river">WATER / CONTEXT ONLY</div>${[['Tent',25,28],['Sleep pad',26,43],['Chair',58,30],['Table',70,52],['Jetboil',53,66],['Food storage',22,78],['Headlamp',73,78],['Power',76,23]].map(([n,x,y],i)=>`<button class="camp-token" data-camp-item="${i}" style="left:${x}%;top:${y}%" aria-pressed="false">${n}</button>`).join('')}</div><article class="lab-panel"><span class="eyebrow">FROM ARRIVAL TO EVENING</span><h3 id="camp-time-title">Afternoon</h3>${range('camp-time','Time of day',0,100,25)}<p id="camp-time-copy">Put things down. Take a breath.</p><p id="camp-selection" aria-live="polite">Choose something to move.</p>${button('RESET THE LAYOUT','camp-reset')}${button('SAVE CAMP PLAN','camp-save')}<p class="fine-print">Layout sketch, not a safety plan. Saved on this device.</p></article></div>`));
  const campItems=$$('[data-camp-item]');const original=campItems.map(b=>[parseFloat(b.style.left),parseFloat(b.style.top)]);let positions=T.store.read('tom-camp-v4',original.map(p=>[...p]));if(!Array.isArray(positions)||positions.length!==original.length)positions=original.map(x=>[...x]);let selectedCamp=0,drag=null;
  function campRender(){campItems.forEach((b,i)=>{b.style.left=clamp(Number(positions[i]?.[0])||20,8,90)+'%';b.style.top=clamp(Number(positions[i]?.[1])||20,12,90)+'%';b.setAttribute('aria-pressed',String(i===selectedCamp))})}
  campItems.forEach((b,i)=>{b.onclick=()=>{selectedCamp=i;$('#camp-selection').textContent=b.textContent+' selected. Drag it, or use arrow keys.';campRender()};b.onpointerdown=e=>{selectedCamp=i;drag=i;b.setPointerCapture?.(e.pointerId);campRender()};b.onpointermove=e=>{if(drag!==i)return;const r=$('#camp-plan').getBoundingClientRect();positions[i]=[clamp((e.clientX-r.left)/r.width*100,8,90),clamp((e.clientY-r.top)/r.height*100,12,90)];campRender()};b.onpointerup=b.onpointercancel=()=>drag=null});
  $('#camp-plan').onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const p=positions[selectedCamp];p[0]=clamp(p[0]+(e.key==='ArrowRight'?2:e.key==='ArrowLeft'?-2:0),8,90);p[1]=clamp(p[1]+(e.key==='ArrowDown'?2:e.key==='ArrowUp'?-2:0),12,90);campRender()};$('#camp-reset').onclick=()=>{positions=original.map(p=>[...p]);campRender()};$('#camp-save').onclick=()=>T.notify(T.store.write('tom-camp-v4',positions)?'Camp arrangement saved on this device.':'Could not save in this browser.');campRender();
  bindRange('camp-time',n=>{const i=clamp(Math.floor(n/25),0,3);$('#camp-time-title').textContent=['Arrival','Afternoon','Golden hour','After dark'][i];$('#camp-time-copy').textContent=['Find a place to pause. The day is still open.','The small things: shelter, a meal, somewhere to sit.','The light changes. The pace changes with it.','Headlamp on. Let the rest of the world quiet down.'][i];$('#camp-plan').style.setProperty('--night',n/125);});
  const tackle=append(section('tackle-box','OPEN THE TACKLE BOX','One more cast.<br><span class="muted">One more idea.</span>','Explore presentations and the questions behind them.',`<div class="lab-tabs" id="tackle-filters">${['All','Moving','Slow','Bottom'].map(x=>`<button data-tackle-filter="${x}" aria-pressed="${x==='All'}">${x}</button>`).join('')}</div><div class="tackle-layout"><div class="tackle-grid" id="tackle-grid"></div><article class="lab-panel" id="tackle-detail" aria-live="polite"><span class="eyebrow">BASS / PICKEREL / CURIOSITY</span><h3>Pick a presentation.</h3><p>Speed, cover, depth, and the way a lure moves are all part of the experiment.</p></article></div>`));
  const lures=[['Spinnerbait','Moving','Flash and vibration. Change the retrieve speed and watch how the presentation changes.'],['Chatterbait','Moving','A vibrating moving presentation. Think about the feel of the retrieve and the water around it.'],['Jig','Bottom','A compact presentation that invites a slower look at bottom contact.'],['Jerkbait','Moving','A rhythm of movement and pauses. The pause is part of the presentation.'],['Paddletail','Moving','A swimming profile. Speed and depth change the path it takes.'],['Ned rig','Bottom','A smaller, slower presentation. Subtle movement becomes the experiment.'],['Fluke','Slow','A soft-plastic profile with room to vary the cadence.'],['Worm','Slow','A familiar starting point with many ways to change the rig and pace.']];const inspected=new Set();
  function tackleRender(filter){$('#tackle-grid').innerHTML=lures.map((l,i)=>({l,i})).filter(({l})=>filter==='All'||l[1]===filter).map(({l,i})=>`<button data-lure="${i}"><span>0${i+1} / ${l[1].toUpperCase()}</span><strong>${l[0]}</strong><span>INSPECT ↗</span></button>`).join('');$$('[data-lure]').forEach(b=>b.onclick=()=>{const i=+b.dataset.lure,[n,k,p]=lures[i];inspected.add(i);$('#tackle-detail').innerHTML=`<span class="eyebrow">${k.toUpperCase()} PRESENTATION</span><h3>${n}</h3><p>${p}</p><p class="fine-print">Adjust for the water and conditions.</p><span>${inspected.size} / ${lures.length} inspected</span>`;change($('#tackle-detail'));if(inspected.size===lures.length){T.unlock('secret');T.notify('Every compartment opened. A little extra curiosity pays off.')}})}
