  const boat=append(section('boat-journal','THE BOAT / THE ONGOING STORY','Always something<br><span class="muted">to figure out.</span>','Explore the topics around the MirroCraft.<br>Current equipment and future ideas stay distinct.',`<div class="learning-grid">${[['The motor','1988 Yamaha 30 hp two-stroke.'],['The workbench','Fuel, spark, and cooling. Ongoing troubleshooting notes.'],['The hull','Deck and drainage upgrades are still in the planning stage.'],['The next trip','Pack up. Head out. Bring back another idea.']].map(([h,p])=>`<details><summary>${h}<span>+</span></summary><p>${p}</p></details>`).join('')}</div><div class="lab-split launch-study"><article class="lab-panel"><span class="eyebrow">A SIMPLE GEOMETRY STUDY</span><h3>Under the surface.</h3>${range('launch-depth','Illustrative water level',0,100,50)}<p id="launch-result"></p><p class="fine-print">No real-world units or safe-launch threshold. This animation cannot assess a ramp, water depth, boat clearance, or launch conditions.</p></article><div class="depth-diagram"><span class="diagram-label">HULL CROSS-SECTION / ABSTRACT MODEL</span><div class="hull-section"></div><div class="water-level" id="water-level"></div><span class="diagram-floor">REFERENCE PLANE</span></div></div><div class="lab-actions">${button('START THE MOTOR ANIMATION','motor-start')}<output id="motor-status" aria-live="polite">A little motion, inspired by the boat.</output></div>`));
  bindRange('launch-depth',n=>{$('#water-level').style.height=n+'%';$('#launch-result').textContent='Water level: '+n+' / 100 in this abstract model.'});$('#motor-start').onclick=()=>{const drawing=$('.boat-drawing');drawing.classList.remove('motor-running');void drawing.offsetWidth;drawing.classList.add('motor-running');$('#motor-status').textContent='Starting…';setTimeout(()=>{$('#motor-status').textContent='Running. Another reason to get out on the water.';drawing.classList.remove('motor-running')},1800)};
  const fire=append(section('campfire','STAY A LITTLE LONGER','Nothing to rush.<br><span class="muted">Nowhere else to be.</span>','A quiet end to the day.',`<div class="campfire-space"><span class="eyebrow">EVENING / OFF THE GRID</span><strong id="fire-line">LET THE DAY<br>SLOW DOWN.</strong><div class="ember-field" aria-hidden="true">${Array.from({length:18},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="lab-actions">${button('ADD A LITTLE WARMTH','fire-wood')}${button('ENTER CAMPFIRE MODE','fire-mode')}<label class="toggle-row">Gentle fire sound<input id="fire-audio" type="checkbox"></label></div><p class="fine-print">Sound starts only when you turn it on.</p></div>`));
  let warmth=0;$('#fire-wood').onclick=()=>{warmth=(warmth+1)%4;$('.campfire-space').style.setProperty('--warmth',.15+warmth*.12);$('#fire-line').innerHTML=['LET THE DAY<br>SLOW DOWN.','ONE MORE<br>STORY.','STAY A<br>LITTLE LONGER.','THE REST<br>CAN WAIT.'][warmth];change($('#fire-line'))};$('#fire-mode').onclick=()=>{const on=document.body.classList.toggle('campfire-mode');$('#fire-mode').textContent=on?'LEAVE CAMPFIRE MODE':'ENTER CAMPFIRE MODE';$('#fire-mode').setAttribute('aria-pressed',String(on))};
  let fireAudio,fireSource;function stopFire(){try{fireSource?.stop();fireAudio?.close()}catch{}fireSource=null;fireAudio=null;$('#fire-audio').checked=false}
  $('#fire-audio').onchange=e=>{if(!e.target.checked){stopFire();return}try{fireAudio=new (window.AudioContext||window.webkitAudioContext)();const buffer=fireAudio.createBuffer(1,fireAudio.sampleRate*2,fireAudio.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+Math.random()*.04-.02)/1.02;data[i]=last}fireSource=fireAudio.createBufferSource();fireSource.buffer=buffer;fireSource.loop=true;const gain=fireAudio.createGain();gain.gain.value=.18;fireSource.connect(gain);gain.connect(fireAudio.destination);fireSource.start()}catch{stopFire();T.notify('Audio is unavailable in this browser.')}};document.addEventListener('visibilitychange',()=>{if(document.hidden)stopFire()});addEventListener('pagehide',stopFire,{once:true});
